    else
      geglu_5120_kernel<false><<<grid, THREADS, 0, stream>>>(x, y);
  } else {
    long long n = rows * inner;
    long long blocks = (n + 255) / 256;
    if (blocks > 1048576) blocks = 1048576;
    geglu_generic_kernel<<<(unsigned)blocks, 256, 0, stream>>>(x, y, rows, inner);
  }
}

